#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys

CURRENT_RELEASE = "1.0"

CAP_CENTS_1_0 = 2400
CREDIT_DIVISOR_1_0 = 10


def assigned_credit_cents_1_0(lines):
    """Release 1.0: each line earns floor(10% of charge), assigned within a
    2400-cent cap shared per account_id, earliest service_on first then
    increasing line_id."""
    credits = {}
    remaining = {}
    ordered = sorted(lines, key=lambda line: (line["service_on"], line["line_id"]))
    for line in ordered:
        uncapped = line["charge_cents"] // CREDIT_DIVISOR_1_0
        cap_left = remaining.setdefault(line["account_id"], CAP_CENTS_1_0)
        credit = min(uncapped, cap_left)
        remaining[line["account_id"]] = cap_left - credit
        credits[line["line_id"]] = credit
    return credits


def quote_1_0(line):
    credit = assigned_credit_cents_1_0([line])[line["line_id"]]
    return {
        "release": "1.0",
        "line_id": line["line_id"],
        "credit_cents": credit,
        "amount_due_cents": line["charge_cents"] - credit,
    }


def handle(request):
    command = request.get("command")
    if command == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    if command == "quote":
        release = request.get("release", CURRENT_RELEASE)
        if release == "1.0":
            return quote_1_0(request["line"])
        return {"error": "unsupported_release"}
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")

import json
import subprocess
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


class QuoteTests(unittest.TestCase):
    def check_request(self, request, expected):
        got = subprocess.run([sys.executable, str(ROOT / "main.py")],
                             input=json.dumps(request), text=True, capture_output=True, check=True)
        self.assertEqual(json.loads(got.stdout), expected)

    def line(self, **overrides):
        line = {
            "line_id": "L-1",
            "account_id": "A",
            "subscription_id": "S",
            "service_on": "2026-04-15",
            "charge_cents": 19999,
        }
        line.update(overrides)
        return line

    def test_issue_example(self):
        self.check_request(
            {"command": "quote", "release": "1.0", "line": self.line()},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 1999, "amount_due_cents": 18000},
        )

    def test_omitted_release_selects_current(self):
        self.check_request(
            {"command": "quote", "line": self.line()},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 1999, "amount_due_cents": 18000},
        )

    def test_credit_rounds_down(self):
        self.check_request(
            {"command": "quote", "line": self.line(charge_cents=5)},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 0, "amount_due_cents": 5},
        )

    def test_cap_2400(self):
        self.check_request(
            {"command": "quote", "line": self.line(charge_cents=30000)},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 2400, "amount_due_cents": 27600},
        )

    def test_zero_charge(self):
        self.check_request(
            {"command": "quote", "line": self.line(charge_cents=0)},
            {"release": "1.0", "line_id": "L-1", "credit_cents": 0, "amount_due_cents": 0},
        )

    def test_response_has_exactly_specified_keys(self):
        got = subprocess.run([sys.executable, str(ROOT / "main.py")],
                             input=json.dumps({"command": "quote", "line": self.line()}),
                             text=True, capture_output=True, check=True)
        self.assertEqual(set(json.loads(got.stdout)),
                         {"release", "line_id", "credit_cents", "amount_due_cents"})
